-- ============================================================================
-- H4 GO-LIVE (HELD): Consequence Modelling flips to 'available', the FOURTH
-- course of the HSE module, at path_order 64.
--
-- DEPLOY GATE. Do NOT run this until a NextGen production upload carries the
-- route /dashboard/apps/consequence. The 78 lessons, the teaching lab
-- (consequenceLab.js) and its three explorer panels (release, fire and harm)
-- ship in the ZIP and NOT in this database, so a flip before the upload puts a
-- live catalogue tile in front of a route that does not exist. This file is
-- written, dry-run and left unapplied on purpose.
--
-- EVERY GRADED VALUE IS CHECKED THREE WAYS, and none restates the generator:
--
--   1. against the ENGINE LEDGER: the values h4_capstone.mjs returned through
--      the vendored engines/hse/consequence.js when this file was generated, to
--      the last bit, so a capstone row an earlier seed left behind, or a move of
--      one part in 1e7, is refused by name;
--   2. by a SECOND ROUTE IN SQL over the inputs the learner is handed: the
--      go-live first proves each shipped prompt is the rendered one byte for
--      byte and carries every input fragment, then recomputes every closed-form
--      field from the published equations (outflow, the pool, the reflected
--      plume, the solid flame chain term by term, Kinney and Graham, and the
--      four probits through the Abramowitz and Stegun erf the engine uses), and
--      asserts the two roots BY THE EQUATION THEY ARE A ROOT OF;
--   3. by the TRAPS the course is built on, 105 wrong methods the
--      discriminate sweep computed through the engine, each of which must miss
--      the seeded value by more than the field's tolerance.
--
-- THE GRADER IS NUMERIC. academy_submit_capstone casts expected, tol and the
-- answer to numeric and passes abs(answer - expected) <= tol. The view factor is
-- graded at twelve decimals (tolerance 5e-13), every other field at six (5e-7).
-- Every field must carry a positive, non-whole expected value at its class's
-- tolerance with a label and a unit, the answer the prompt asks for must pass,
-- and one unit either side of it in the last asked decimal must fail.
--
-- EVERY DENOMINATOR BELOW IS A FLOAT, ON PURPOSE. Postgres divides integer by
-- integer as an integer, and the generator refuses to emit a bare integer
-- denominator.
--
-- EVERY REFUSAL THAT READS A GRADED VALUE NAMES IT as tier/key.
-- ============================================================================

do $$
declare
  v_structures int; v_questions int; v_capstones int; v_lessons int;
  v_modules int; v_graded int; v_available int; v_soon int; v_n int; v_k int;
  v_names text; v_prompt text; v_x double precision; v_wrong double precision;
  v_g_okan_condensate_leak_mass_rate_kg_s double precision;
  v_g_okan_gas_riser_choked_mass_rate_kg_s double precision;
  v_g_okan_vent_subsonic_mass_rate_kg_s double precision;
  v_g_okan_deck_spill_equivalent_diameter_m double precision;
  v_g_okan_plume_receptor_concentration_ppm double precision;
  v_g_okan_plume_far_distance_m double precision;
  v_g_yokri_flame_length_with_wind_m double precision;
  v_g_yokri_flame_tilt_deg double precision;
  v_g_yokri_surface_emissive_power_mudan_w_m2 double precision;
  v_g_yokri_surface_emissive_power_actual_w_m2 double precision;
  v_g_yokri_view_factor_max double precision;
  v_g_yokri_solid_flame_heat_flux_w_m2 double precision;
  v_g_pennington_blast_overpressure_pa double precision;
  v_g_pennington_blast_distance_for_overpressure_m double precision;
  v_g_pennington_overpressure_fatality_probability double precision;
  v_g_pennington_thermal_lethality_probability double precision;
  v_g_pennington_toxic_lethality_probability double precision;
  v_g_pennington_ammonia_lethality_probability double precision;
begin

  -- ---------------------------------------------------------------- shape
  select count(*) into v_structures from public.academy_course_structures
   where app_slug = 'consequence' and active;
  if v_structures <> 3 then
    raise exception 'H4 go-live refused: consequence has % active deep structures, expected 3', v_structures;
  end if;

  select count(*) into v_questions from public.academy_quiz_questions where app_slug = 'consequence';
  if v_questions <> 396 then
    raise exception 'H4 go-live refused: consequence has % quiz questions, expected 396', v_questions;
  end if;

  select count(*) into v_n from (
    select tier from public.academy_quiz_questions where app_slug = 'consequence'
     group by tier having count(*) <> 132) t;
  if v_n <> 0 then
    raise exception 'H4 go-live refused: % tier(s) do not carry exactly 132 questions', v_n;
  end if;

  select count(*) into v_n from (
    select tier, module_key from public.academy_quiz_questions
     where app_slug = 'consequence' and scope = 'module'
     group by tier, module_key having count(*) <> 15) t;
  if v_n <> 0 then
    raise exception 'H4 go-live refused: % module bank(s) do not carry exactly 15 questions', v_n;
  end if;

  select count(*) into v_n from (
    select tier from public.academy_quiz_questions
     where app_slug = 'consequence' and scope = 'final'
     group by tier having count(*) <> 42) t;
  if v_n <> 0 then
    raise exception 'H4 go-live refused: % final exam(s) do not carry exactly 42 questions', v_n;
  end if;

  -- A key outside its own options is unanswerable, and a count of rows cannot
  -- see it.
  select count(*) into v_n from public.academy_quiz_questions
   where app_slug = 'consequence'
     and (jsonb_array_length(options) <> 4 or answer_index < 0 or answer_index > 3);
  if v_n <> 0 then
    raise exception 'H4 go-live refused: % question(s) do not offer four options with a key inside them', v_n;
  end if;

  select count(*) into v_lessons
    from public.academy_course_structures s,
         lateral jsonb_array_elements(s.structure->'modules') m,
         lateral jsonb_array_elements_text(m->'lesson_keys') lk
   where s.app_slug = 'consequence' and s.active;
  if v_lessons <> 78 then
    raise exception 'H4 go-live refused: consequence carries % lesson keys, expected 78', v_lessons;
  end if;

  select count(*) into v_modules
    from public.academy_course_structures s,
         lateral jsonb_array_elements(s.structure->'modules') m
   where s.app_slug = 'consequence' and s.active;
  if v_modules <> 18 then
    raise exception 'H4 go-live refused: consequence carries % modules, expected 18 (six per tier)', v_modules;
  end if;

  select count(*) into v_n from (
    select distinct qq.tier, qq.module_key from public.academy_quiz_questions qq
     where qq.app_slug = 'consequence' and qq.scope = 'module'
       and not exists (
         select 1 from public.academy_course_structures s,
              lateral jsonb_array_elements(s.structure->'modules') m
          where s.app_slug = qq.app_slug and s.tier = qq.tier and s.active
            and m->>'key' = qq.module_key)) t;
  if v_n <> 0 then
    raise exception 'H4 go-live refused: % module bank(s) are keyed to a module the structure does not declare', v_n;
  end if;

  select count(*) into v_capstones from public.academy_capstones where app_slug = 'consequence';
  if v_capstones <> 3 then
    raise exception 'H4 go-live refused: consequence has % capstones, expected 3', v_capstones;
  end if;

  select count(*) into v_graded from public.academy_capstones c,
         lateral jsonb_array_elements(c.fields) f where c.app_slug = 'consequence';
  if v_graded <> 18 then
    raise exception 'H4 go-live refused: consequence has % graded capstone fields, expected 18', v_graded;
  end if;

  select count(*) into v_n from (
    select c.tier from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
     where c.app_slug = 'consequence' group by c.tier having count(*) <> 6) t;
  if v_n <> 0 then
    raise exception 'H4 go-live refused: % tier(s) do not grade exactly six fields', v_n;
  end if;

  if not exists (select 1 from public.academy_apps
                  where slug = 'consequence' and module = 'hse'
                    and path_order = 64 and prereq_slug is null) then
    raise exception 'H4 go-live refused: the consequence catalogue row is not hse at path_order 64 with no prerequisite';
  end if;

  if exists (select 1 from public.academy_apps where path_order = 64 and slug <> 'consequence') then
    raise exception 'H4 go-live refused: another course already holds path_order 64';
  end if;

  -- ------------------------------------------------- the grader is numeric
  -- Every field a positive, non-whole number at its class's tolerance (twelve
  -- decimals at 5e-13, six at 5e-7), with a label and a unit.
  select count(*), string_agg(c.tier || '/' || (f->>'key'), ', ')
    into v_n, v_names
    from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
   where c.app_slug = 'consequence'
     and (jsonb_typeof(f->'expected') <> 'number' or jsonb_typeof(f->'tol') <> 'number'
          or (f->>'expected')::numeric <= 0
          or (f->>'expected')::numeric = round((f->>'expected')::numeric)
          or (f->>'tol')::numeric <> case when f->>'key' in ('okan_condensate_leak_mass_rate_kg_s', 'okan_gas_riser_choked_mass_rate_kg_s', 'okan_vent_subsonic_mass_rate_kg_s', 'okan_deck_spill_equivalent_diameter_m', 'okan_plume_receptor_concentration_ppm', 'okan_plume_far_distance_m', 'yokri_flame_length_with_wind_m', 'yokri_flame_tilt_deg', 'yokri_surface_emissive_power_mudan_w_m2', 'yokri_surface_emissive_power_actual_w_m2', 'yokri_solid_flame_heat_flux_w_m2', 'pennington_blast_overpressure_pa', 'pennington_blast_distance_for_overpressure_m', 'pennington_overpressure_fatality_probability', 'pennington_thermal_lethality_probability', 'pennington_toxic_lethality_probability', 'pennington_ammonia_lethality_probability') then 0.0000005 else 0.0000000000005 end
          or (f->>'key') not in ('okan_condensate_leak_mass_rate_kg_s', 'okan_gas_riser_choked_mass_rate_kg_s', 'okan_vent_subsonic_mass_rate_kg_s', 'okan_deck_spill_equivalent_diameter_m', 'okan_plume_receptor_concentration_ppm', 'okan_plume_far_distance_m', 'yokri_flame_length_with_wind_m', 'yokri_flame_tilt_deg', 'yokri_surface_emissive_power_mudan_w_m2', 'yokri_surface_emissive_power_actual_w_m2', 'yokri_view_factor_max', 'yokri_solid_flame_heat_flux_w_m2', 'pennington_blast_overpressure_pa', 'pennington_blast_distance_for_overpressure_m', 'pennington_overpressure_fatality_probability', 'pennington_thermal_lethality_probability', 'pennington_toxic_lethality_probability', 'pennington_ammonia_lethality_probability')
          or coalesce(f->>'label', '') = '' or coalesce(f->>'unit', '') = '');
  if v_n <> 0 then
    raise exception 'H4 go-live refused: % graded field(s) are not a positive non-whole number at their class tolerance with a label and a unit: %', v_n, v_names;
  end if;

  -- THE GRADER, SIMULATED ON THE SEEDED ROW. The answer the prompt asks for,
  -- the expected value to its class's decimals, must pass
  -- abs(answer - expected) <= tol in numeric exactly as academy_submit_capstone
  -- computes it, and one unit in the last decimal either side of it must fail.
  select count(*), string_agg(t.tier || '/' || t.k, ', ')
    into v_n, v_names
    from (select c.tier, f->>'key' k, (f->>'expected')::numeric e, (f->>'tol')::numeric tl,
                 case when f->>'key' in ('okan_condensate_leak_mass_rate_kg_s', 'okan_gas_riser_choked_mass_rate_kg_s', 'okan_vent_subsonic_mass_rate_kg_s', 'okan_deck_spill_equivalent_diameter_m', 'okan_plume_receptor_concentration_ppm', 'okan_plume_far_distance_m', 'yokri_flame_length_with_wind_m', 'yokri_flame_tilt_deg', 'yokri_surface_emissive_power_mudan_w_m2', 'yokri_surface_emissive_power_actual_w_m2', 'yokri_solid_flame_heat_flux_w_m2', 'pennington_blast_overpressure_pa', 'pennington_blast_distance_for_overpressure_m', 'pennington_overpressure_fatality_probability', 'pennington_thermal_lethality_probability', 'pennington_toxic_lethality_probability', 'pennington_ammonia_lethality_probability') then 6 else 12 end dp
            from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
           where c.app_slug = 'consequence') t
   where abs(round(t.e, t.dp) - t.e) > t.tl
      or abs(round(t.e, t.dp) + power(10::numeric, -t.dp) - t.e) <= t.tl
      or abs(round(t.e, t.dp) - power(10::numeric, -t.dp) - t.e) <= t.tl;
  if v_n <> 0 then
    raise exception 'H4 go-live refused: % graded field(s) either fail the answer the prompt asks for or pass one a unit off in its last decimal: %', v_n, v_names;
  end if;


  -- ---------------------------------------- the prompts the learner reads

  -- beginner: the rendered prompt, byte for byte, and the dataset and title.
  select prompt into v_prompt from public.academy_capstones where app_slug = 'consequence' and tier = 'beginner';
  if md5(v_prompt) <> '2741c28ac883c4d8c538e2967eee9393' then
    raise exception 'H4 go-live refused: the beginner prompt is not the prompt gen_course.py rendered from the engine inputs (md5 %)', md5(v_prompt);
  end if;
  if not exists (select 1 from public.academy_capstones where app_slug = 'consequence' and tier = 'beginner'
                    and cert_tier = 'associate' and dataset = 'OKAN, a gas and condensate platform loss of containment day' and title = 'How much gets out, and where it goes') then
    raise exception 'H4 go-live refused: the beginner capstone does not carry the certificate tier, dataset and title gen_course.py rendered';
  end if;
  -- Every input fragment the second route reads is stated, matched as a
  -- literal substring with strpos (an underscore or a percent sign in a LIKE
  -- pattern is a wildcard).
  select count(*) into v_n from unnest(array['OKAN, a gas and condensate platform, on a loss of containment day. The properties below are illustrative, chosen for this exercise. Every pressure is absolute, and ambient is 101325 Pa.', 'CONDENSATE: a hole of 0.041 m diameter in the stabiliser bottoms line, discharge coefficient 0.62, condensate density 786 kg/m3, 4.37 m of liquid above the hole and 310000 Pa above the liquid.', 'RISER: a hole of 0.059 m diameter in the gas riser, discharge coefficient 0.62, gas at 4700000 Pa and 308.15 K, molar mass 0.0187 kg/mol, heat capacity ratio 1.28.', 'VENT: the flash gas vent, the same gas through a hole of the same 0.059 m and the same discharge coefficient 0.62, at 128000 Pa and 308.15 K, molar mass 0.0187 kg/mol, heat capacity ratio 1.28.', 'DECK SPILL: 24.8 m3 spilled on an open deck with no bund, spreading to a stated thickness of 0.017 m.', 'PLUME: a sustained release of hydrogen sulphide (molar mass 34.08 g/mol) at 0.815 kg/s from a vent stack 12 m high, in a 4.2 m/s wind, Pasquill-Gifford class D, Briggs rural sigmas. The receptor is 620 m downwind, 35 m off the centreline and 1.7 m above the ground; convert at 25 C and 101325 Pa.', 'REACH: the same 0.815 kg/s release from the same 12 m stack in the same 4.2 m/s wind at night, class E, read on the centreline 1.7 m above the ground, against a stated concentration of 21 mg/m3.']) l where strpos(v_prompt, l) = 0;
  if v_n <> 0 then
    raise exception 'H4 go-live refused: % beginner input fragment(s) the second route reads are not stated in the shipped prompt', v_n;
  end if;

  -- intermediate: the rendered prompt, byte for byte, and the dataset and title.
  select prompt into v_prompt from public.academy_capstones where app_slug = 'consequence' and tier = 'intermediate';
  if md5(v_prompt) <> 'f02dc90e3fdfb596a62742b5930aa0c1' then
    raise exception 'H4 go-live refused: the intermediate prompt is not the prompt gen_course.py rendered from the engine inputs (md5 %)', md5(v_prompt);
  end if;
  if not exists (select 1 from public.academy_capstones where app_slug = 'consequence' and tier = 'intermediate'
                    and cert_tier = 'professional' and dataset = 'YOKRI, a tank farm bund fire on a windy afternoon' and title = 'What the fire radiates, step by step') then
    raise exception 'H4 go-live refused: the intermediate capstone does not carry the certificate tier, dataset and title gen_course.py rendered';
  end if;
  -- Every input fragment the second route reads is stated, matched as a
  -- literal substring with strpos (an underscore or a percent sign in a LIKE
  -- pattern is a wildcard).
  select count(*) into v_n from unnest(array['YOKRI, a bund fire in a tank farm on a windy afternoon, worked through the solid flame model. The properties below are illustrative, chosen for this exercise.', 'THE POOL: 31.5 m diameter, kerosene, its burning flux from the Babrauskas table the engine carries; heat of combustion 43000000 J/kg.', 'THE AIR: wind at 10 m 6 m/s, air density 1.2 kg/m3, air kinematic viscosity 1.48e-5 m2/s. Take the flame length by Thomas with wind and the tilt from the wind, the flame base radius half the pool diameter.', 'THE FLAME SURFACE: compute the surface emissive power two ways, from the diameter (Mudan) and from a radiative fraction of 0.235 with a soot fraction of 0.8 and the engine''s default soot emissive power; the heat flux uses the second.', 'THE TARGET: at ground level 72 m downwind of the pool centre, the flame leaning toward it, with a stated atmospheric transmissivity of 0.765.']) l where strpos(v_prompt, l) = 0;
  if v_n <> 0 then
    raise exception 'H4 go-live refused: % intermediate input fragment(s) the second route reads are not stated in the shipped prompt', v_n;
  end if;

  -- advanced: the rendered prompt, byte for byte, and the dataset and title.
  select prompt into v_prompt from public.academy_capstones where app_slug = 'consequence' and tier = 'advanced';
  if md5(v_prompt) <> '69b273ba05258e2364c028584ca3f54f' then
    raise exception 'H4 go-live refused: the advanced prompt is not the prompt gen_course.py rendered from the engine inputs (md5 %)', md5(v_prompt);
  end if;
  if not exists (select 1 from public.academy_capstones where app_slug = 'consequence' and tier = 'advanced'
                    and cert_tier = 'expert' and dataset = 'PENNINGTON, a storage terminal and the harm three hazards do' and title = 'Who is hurt, and with what probability') then
    raise exception 'H4 go-live refused: the advanced capstone does not carry the certificate tier, dataset and title gen_course.py rendered';
  end if;
  -- Every input fragment the second route reads is stated, matched as a
  -- literal substring with strpos (an underscore or a percent sign in a LIKE
  -- pattern is a wildcard).
  select count(*) into v_n from unnest(array['PENNINGTON, a storage terminal, and the harm a vapour cloud explosion, a fire and two toxic releases do to the people nearby. The properties below are illustrative, chosen for this exercise. Ambient is 101325 Pa.', 'BLAST: the cloud is stated as 2650 kg of TNT, a free air burst, Kinney and Graham. The control room is 145 m away. Find also the distance at which the peak side-on overpressure is 19800 Pa. A workshop takes 65000 Pa; use the HSC overpressure fatality probit.', 'FIRE: a heat flux of 11900 W/m2 for 60 s, the eisenberg thermal probit.', 'CHLORINE: 270 ppm for 20 minutes, the lees-chlorine toxic probit.', 'AMMONIA: 11050 mg/m3 for 12 minutes, the lees-ammonia toxic probit, molar mass 17.031 g/mol, the air at 288.15 K and 101325 Pa.']) l where strpos(v_prompt, l) = 0;
  if v_n <> 0 then
    raise exception 'H4 go-live refused: % advanced input fragment(s) the second route reads are not stated in the shipped prompt', v_n;
  end if;

  -- --------------------------------------- the eighteen graded values
  select (f->>'expected')::double precision into v_g_okan_condensate_leak_mass_rate_kg_s
    from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
   where c.app_slug = 'consequence' and c.tier = 'beginner' and f->>'key' = 'okan_condensate_leak_mass_rate_kg_s';
  select (f->>'expected')::double precision into v_g_okan_gas_riser_choked_mass_rate_kg_s
    from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
   where c.app_slug = 'consequence' and c.tier = 'beginner' and f->>'key' = 'okan_gas_riser_choked_mass_rate_kg_s';
  select (f->>'expected')::double precision into v_g_okan_vent_subsonic_mass_rate_kg_s
    from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
   where c.app_slug = 'consequence' and c.tier = 'beginner' and f->>'key' = 'okan_vent_subsonic_mass_rate_kg_s';
  select (f->>'expected')::double precision into v_g_okan_deck_spill_equivalent_diameter_m
    from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
   where c.app_slug = 'consequence' and c.tier = 'beginner' and f->>'key' = 'okan_deck_spill_equivalent_diameter_m';
  select (f->>'expected')::double precision into v_g_okan_plume_receptor_concentration_ppm
    from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
   where c.app_slug = 'consequence' and c.tier = 'beginner' and f->>'key' = 'okan_plume_receptor_concentration_ppm';
  select (f->>'expected')::double precision into v_g_okan_plume_far_distance_m
    from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
   where c.app_slug = 'consequence' and c.tier = 'beginner' and f->>'key' = 'okan_plume_far_distance_m';
  select (f->>'expected')::double precision into v_g_yokri_flame_length_with_wind_m
    from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
   where c.app_slug = 'consequence' and c.tier = 'intermediate' and f->>'key' = 'yokri_flame_length_with_wind_m';
  select (f->>'expected')::double precision into v_g_yokri_flame_tilt_deg
    from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
   where c.app_slug = 'consequence' and c.tier = 'intermediate' and f->>'key' = 'yokri_flame_tilt_deg';
  select (f->>'expected')::double precision into v_g_yokri_surface_emissive_power_mudan_w_m2
    from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
   where c.app_slug = 'consequence' and c.tier = 'intermediate' and f->>'key' = 'yokri_surface_emissive_power_mudan_w_m2';
  select (f->>'expected')::double precision into v_g_yokri_surface_emissive_power_actual_w_m2
    from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
   where c.app_slug = 'consequence' and c.tier = 'intermediate' and f->>'key' = 'yokri_surface_emissive_power_actual_w_m2';
  select (f->>'expected')::double precision into v_g_yokri_view_factor_max
    from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
   where c.app_slug = 'consequence' and c.tier = 'intermediate' and f->>'key' = 'yokri_view_factor_max';
  select (f->>'expected')::double precision into v_g_yokri_solid_flame_heat_flux_w_m2
    from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
   where c.app_slug = 'consequence' and c.tier = 'intermediate' and f->>'key' = 'yokri_solid_flame_heat_flux_w_m2';
  select (f->>'expected')::double precision into v_g_pennington_blast_overpressure_pa
    from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
   where c.app_slug = 'consequence' and c.tier = 'advanced' and f->>'key' = 'pennington_blast_overpressure_pa';
  select (f->>'expected')::double precision into v_g_pennington_blast_distance_for_overpressure_m
    from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
   where c.app_slug = 'consequence' and c.tier = 'advanced' and f->>'key' = 'pennington_blast_distance_for_overpressure_m';
  select (f->>'expected')::double precision into v_g_pennington_overpressure_fatality_probability
    from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
   where c.app_slug = 'consequence' and c.tier = 'advanced' and f->>'key' = 'pennington_overpressure_fatality_probability';
  select (f->>'expected')::double precision into v_g_pennington_thermal_lethality_probability
    from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
   where c.app_slug = 'consequence' and c.tier = 'advanced' and f->>'key' = 'pennington_thermal_lethality_probability';
  select (f->>'expected')::double precision into v_g_pennington_toxic_lethality_probability
    from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
   where c.app_slug = 'consequence' and c.tier = 'advanced' and f->>'key' = 'pennington_toxic_lethality_probability';
  select (f->>'expected')::double precision into v_g_pennington_ammonia_lethality_probability
    from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
